['Light/Clean','Dark/Clean'].forEach(function(app){var p=H.page('Proto macOS '+app.split('/')[0]);var s=p.layers.find(function(l){return l.name==='Screen/macos/'+app+'/settings-general';});var out=[];function walk(l){if(['helper','section:Messages','section:Workspace','group:Messages','group:Workspace','link:settings-general'].indexOf(l.name)>=0)out.push({name:l.name,w:l.frame.width,h:l.frame.height,y:l.frame.y,pad:l.stackLayout?l.stackLayout.padding:null,radii:l.style.corners?l.style.corners.radii:null});(l.layers||[]).forEach(walk);}walk(s);console.log(JSON.stringify({app:app,ink:H.hex(app,'ink'),tertiary:H.hex(app,'tertiary'),panel:H.hex(app,'panel'),surface:H.hex(app,'surface'),geometry:out}));});